NAV=[('index.html','Home'),('about.html','About'),('academics.html','Academics'),('student-life.html','Student Life'),('student-projects.html','Projects'),('admissions.html','Admissions')]
def page(fn,title,body):
    def dd(l,h,it):return f'<li class="dd"><a href="{h}">{l} &#9662;</a><ul>'+''.join(f'<li><a href="{x}">{y}</a></li>' for x,y in it)+'</ul></li>'
    nav='<li><a href="index.html">Home</a></li>'+dd('Our School','about.html',[('about.html','About Us'),('about.html#message','Leadership Message'),('about.html#learning','Learning Environment'),('admissions.html#faq','FAQ')])+dd('Academics','academics.html',[('academics.html','Programs'),('admissions.html','Admissions'),('admissions.html#enquiry','Enquiry Form')])+'<li><a href="student-life.html">Student Life</a></li><li><a href="student-projects.html">Projects</a></li>'+dd('News &amp; Events','news.html',[('news.html','News'),('gallery.html','Gallery')])+'<li><a href="contact.html">Contact</a></li><li class="ap"><a class="apply" href="admissions.html#enquiry">Apply for Admission</a></li>'
    f='<footer><div class="wrap grid"><div><img data-p="logo.png" alt="Monduli Valley logo" style="width:56px;background:#fff;border-radius:50%"><p><b>Monduli Valley Primary School</b><br>Empowering Young Minds</p><p>Social media: [add official links]</p></div><div><b>Explore</b><br><a href="about.html">About Us</a><br><a href="academics.html">Academics</a><br><a href="student-projects.html">Student Projects</a><br><a href="admissions.html">Admissions</a></div><div><b>Contacts</b><br>[Official School Address]<br>[School Telephone Number]<br>[School Email]<br>Hours: [Opening hours]</div><div><b>News</b><br><a href="news.html">Sample: Admissions Enquiries</a><br><a href="news.html">Sample: Showcase Day</a></div></div><div class="wrap"><small>&copy; <span class="yr"></span> Monduli Valley Primary School. Prototype with illustrative content.</small></div></footer><button id="top" class="btn" aria-label="Back to top">&uarr;</button>'

    open(fn,'w').write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Monduli Valley Primary School</title><link rel="stylesheet" href="css/style.css"></head><body><header><div class="wrap bar"><a class="brand" href="index.html"><img data-p="logo.png" alt="Monduli Valley logo"><span>Monduli Valley<small>Primary School</small></span></a><button id="menu" aria-label="Menu" aria-expanded="false">Menu</button><nav aria-label="Main"><ul>{nav}</ul></nav></div></header><main>{body}</main>{f}<script src="js/main.js"></script></body></html>')
def hero(h,p,img,extra=''):
    return f'<section class="hero"><img data-p="{img}" alt="{h}" class="" loading="eager"><div class="wrap"><p class="eyebrow">MONDULI VALLEY PRIMARY SCHOOL</p><h1>{h}</h1><p style="max-width:36em">{p}</p>{extra}</div></section>'
def two(h,p,img,alt,cta=''):
    return f'<section><div class="wrap two rv"><div><h2 id="{h.split()[0].lower()}">{h}</h2><p>{p}</p>{cta}</div><img data-p="{img}" alt="{alt}" class="pic"></div></section>'
CTA='<section class="lb"><div class="wrap"><h2>Join our community</h2><a class="btn" href="admissions.html">Learn About Admissions</a> <a class="btn dk" href="contact.html">Contact the School</a></div></section>'
N='<p class="note">Illustrative content. [Official details to be supplied by the school.]</p>'
lv=''.join(f'<div class="card rv"><img data-p="{i}" alt="{t}" class="pic"><div class="body"><h3>{t}</h3><p>{d}</p></div></div>' for t,d,i in [('Pre-Primary','A gentle start to learning through play and early literacy.','pre.jpg'),('Primary: Standard 1-4','Building strong reading, writing and number foundations.','prim.jpg'),('Upper Primary: Standard 5-7','Deepening knowledge and confidence for the next stage.','upper.jpg')])
page('index.html','Home',hero('Empowering Young Minds. Inspiring Bright Futures.','A warm community where children learn, create and grow in character.','hero-school.jpg','<p><a class="btn" href="about.html">Explore Our School</a> <a class="btn alt" href="admissions.html">Admissions</a></p>')+two('Welcome to Monduli Valley','An English-medium school for Pre-Primary to Standard 7. Our motto: Empowering Young Minds.','school-environment.jpg','School environment','<a href="about.html">About Us</a>')+f'<section class="alt-bg"><div class="wrap"><h2>Learning journey</h2><div class="grid">{lv}</div></div></section>'+two('Learning beyond the classroom','Practical projects build curiosity, creativity, teamwork and problem-solving.','classroom-learning.jpg','Hands-on learning','<a class="btn" href="student-projects.html">See Student Projects</a>')+'<section class="alt-bg"><div class="wrap"><h2>Featured projects</h2>'+N+'<div class="grid" id="projects-home"></div><p><a href="student-projects.html">View all projects</a></p></div></section>'+CTA)
page('about.html','About Us',hero('About Us','Our school, our values, our learning environment.','school-environment.jpg')+'<section><div class="wrap"><h2>Overview</h2><p>[School overview to be supplied.]</p><h2>Vision</h2><p>[Vision statement]</p><h2>Mission</h2><p>[Mission statement]</p><h2>Core values</h2><p>[Core values]</p><h2 id="message">Message from school leadership</h2><p>[Welcome message from the headmaster]</p>'+N+'</div></section>'+two('Learning environment','Welcoming spaces for children to learn.','classroom-learning.jpg','Classroom')+CTA)
page('academics.html','Academics',hero('Academics','From Pre-Primary to Standard 7.','classroom-learning.jpg')+f'<section><div class="wrap"><div class="grid">{lv}</div><h2>Teaching approach</h2><p>[Official curriculum and approach to be supplied.] We aim to combine strong foundations with practical problem-solving, creativity and collaboration.</p>{N}</div></section>'+CTA)
page('student-life.html','Student Life',hero('Student Life','Beyond the classroom.','sport-1.jpg')+'<section><div class="wrap"><h2>Sports, clubs, arts and events</h2><p>Proposed examples: team games, creative arts, celebrations, leadership roles and practical life skills.</p>'+N+'</div></section>'+two('Teamwork','Children learn collaboration through shared activities.','sport-2.jpg','Pupils in team activity')+CTA)
page('student-projects.html','Student Projects',hero('Learning by Doing. Creating for the Future.','Practical exploration, creative projects and collaboration.','robotics.jpg')+'<section><div class="wrap">'+N+'<div id="projects" class="grid"></div></div></section>'+CTA)
form='<form data-demo novalidate><label for="n">Parent or guardian name</label><input id="n" required><label for="p">Phone number</label><input id="p" type="tel" required><label for="e">Email (optional)</label><input id="e" type="email"><label for="l">Intended entry level</label><select id="l"><option>Pre-Primary</option><option>Standard 1-4</option><option>Standard 5-7</option></select><label for="m">Message</label><textarea id="m" rows="4" required></textarea><p class="note">Demonstration form: nothing is sent to the school.</p><button class="btn">Submit</button></form>'
page('admissions.html','Admissions',hero('Admissions','A simple path for parents.','school-environment.jpg')+'<section><div class="wrap"><h2>Levels</h2><p>Pre-Primary to Standard 7.</p><h2>Requirements, steps and fees</h2><p>[Official admission requirements, steps, fees and deadlines to be supplied.]</p><h2 id="faq">FAQ</h2><details><summary>How do I apply?</summary><p>[Process to be confirmed.]</p></details></div></section><section class="lb" id="enquiry"><div class="wrap"><h2>Enquiry</h2>'+form+'</div></section>')
page('news.html','News',hero('News','Sample announcements for demonstration.','news-1.jpg')+'<section><div class="wrap"><p class="note">All articles are sample content.</p><div id="news" class="grid"></div></div></section>')
page('gallery.html','Gallery',hero('Gallery','Illustrative stock photography, not actual school photos.','school-1.jpg')+'<section><div class="wrap"><div id="gallery" class="grid"></div></div></section>')
page('contact.html','Contact',hero('Contact Us','We would love to hear from you.','school-environment.jpg')+'<section><div class="wrap two"><div><p>[Official School Address]<br>[School Telephone Number]<br>[School Email]<br>Map: [location placeholder]</p></div><form data-demo novalidate><label for="a">Name</label><input id="a" required><label for="b">Email or phone</label><input id="b" required><label for="c">Subject</label><input id="c" required><label for="d">Message</label><textarea id="d" rows="4" required></textarea><p class="note">Demonstration form: nothing is sent.</p><button class="btn">Send</button></form></div></section>')

